INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Going concern representation
(1, 'Written Representations', 'During the audit of Sandridge Technologies for the year ended December 31, 2025, the engagement team at Kessler & Moore notes recurring operating losses and negative cash flows. The partner asks management to include a going concern representation in the management representation letter. Under AU-C 580, which going concern representation should management provide?', '["A representation regarding management''s plans to mitigate the going concern doubt and its assessment of the entity''s ability to continue as a going concern", "A binding pledge that the entity will remain solvent for at least 24 months after the balance sheet date", "A certification from management that no substantial doubt about going concern currently exists", "A statement that the auditor bears sole responsibility for evaluating the entity''s going concern status"]'::jsonb, 0, 'Under AU-C 580.A39, when going concern issues exist, the representation letter should include management''s disclosure of its plans intended to mitigate the adverse effects and its assessment of the entity''s ability to continue as a going concern. Unlike a binding pledge of solvency, which is neither required nor appropriate, the standard calls for management to describe its plans and assessment rather than certify a particular outcome.', 'medium', 2),

-- Q2: medium / L3 — Selection and application of accounting policies
(1, 'Written Representations', 'Birchwood Industries changed its depreciation method from double-declining balance to straight-line during the 2025 fiscal year. The audit team at Clarkson & Hayes drafts the management representation letter. Under AU-C 580, management should represent regarding this accounting policy change that:', '["The change was mandated by the external auditor as a condition of issuing an unmodified opinion", "The significant accounting policies selected and applied are appropriate under the applicable financial reporting framework", "Accounting policies are selected at the auditor''s discretion and management bears no responsibility for the selection", "The entity will revert to the previous depreciation method if the auditor disagrees with the change"]'::jsonb, 1, 'Under AU-C 580.11(a), management must represent that the significant accounting policies selected and applied are appropriate under the applicable financial reporting framework. Although the auditor evaluates the appropriateness of policy choices, management retains full responsibility for selecting policies rather than relying on auditor direction.', 'medium', 3),

-- Q3: easy / L1 — Addressee of the representation letter
(1, 'Written Representations', 'To whom is the management representation letter addressed under AU-C 580?', '["The SEC or applicable regulatory body", "The entity''s board of directors or audit committee", "The auditor performing the engagement", "The entity''s shareholders or investors"]'::jsonb, 2, 'Under AU-C 580.14, the management representation letter is addressed to the auditor. It is a direct communication from management to the engagement auditor confirming key matters discussed during the audit. Unlike the auditor''s report, which is directed to shareholders or the board, the representation letter flows from management to the auditor rather than to external parties.', 'easy', 1),

-- Q4: medium / L2 — Completeness of contingent liabilities disclosure
(1, 'Written Representations', 'The engagement team at Westbrook & Ellis is finalizing the audit of Ridgecrest Energy Corp. for the year ended December 31, 2025. Ridgecrest faces two pending environmental lawsuits. When drafting the management representation letter, the team includes a representation about contingent liabilities. Under AU-C 580, this representation should state that management has:', '["Resolved all pending litigation before the auditor''s report date", "Estimated the maximum possible loss for each individual contingent liability", "Determined that no contingent liabilities requiring disclosure exist at year-end", "Disclosed to the auditor all known actual or possible litigation, claims, and assessments whose effects should be considered when preparing the financial statements"]'::jsonb, 3, 'Under AU-C 580.A11, management represents that all known actual or possible litigation, claims, and assessments whose effects should be considered in the financial statements have been disclosed to the auditor. Unlike a requirement to resolve all litigation, the standard requires disclosure of all known items rather than settlement or elimination of contingencies before the report date.', 'medium', 2),

-- Q5: easy / L1 — Period covered by written representations
(1, 'Written Representations', 'What period should the management representation letter cover under AU-C 580?', '["All periods referred to in the auditor''s report", "Only the 12-month period immediately preceding the report date", "The five most recent fiscal years regardless of audit scope", "Only the current fiscal year, excluding any comparative periods"]'::jsonb, 0, 'Under AU-C 580.15, written representations cover all periods referred to in the auditor''s report. For comparative financial statements, this includes all periods presented rather than only the current year. Although a single-year audit covers just one period, when comparative statements are presented, the letter must encompass every period on which the auditor is opining.', 'easy', 1),

-- Q6: medium / L3 — Availability of all financial records and data
(1, 'Written Representations', 'During the audit of Oakview Healthcare Systems for the year ended December 31, 2025, the CFO asks the engagement team at Pemberton & Associates why the representation letter requires a statement about providing access to all records. The engagement partner explains that under AU-C 580, the primary purpose of this representation is to:', '["Transfer legal liability for any undetected misstatements from the auditor to management", "Confirm that management has provided the auditor with all relevant financial records, complete information, and unrestricted access to persons within the entity", "Eliminate the need for the auditor to perform substantive testing of completeness assertions", "Certify that the auditor has personally inspected every financial record maintained by the entity"]'::jsonb, 1, 'Under AU-C 580.11(b), management represents that it has provided the auditor with all relevant financial records and related data, complete information on all transactions, and unrestricted access to persons within the entity. However, the representation does not transfer liability or eliminate the need for further audit procedures — it formalizes management''s commitment to full disclosure rather than substituting for substantive testing.', 'medium', 3),

-- Q7: medium / L3 — Uncorrected misstatements summary attached to letter
(1, 'Written Representations', 'While finalizing the audit of Crestline Manufacturing for the year ended December 31, 2025, the engagement team at Harper & Webb identifies three uncorrected misstatements totaling $18,000, each deemed immaterial individually and in aggregate. The team prepares the management representation letter. Under AU-C 580, the auditor should:', '["Exclude the uncorrected misstatements from the letter since they are individually and aggregately immaterial", "Require management to correct all identified misstatements regardless of materiality before signing the letter", "Attach a summary of the uncorrected misstatements to the representation letter and obtain management''s acknowledgment that the effects are immaterial to the financial statements", "Report the uncorrected misstatements only to those charged with governance without referencing them in the letter"]'::jsonb, 2, 'Under AU-C 580.12, the auditor attaches a summary of uncorrected misstatements to the management representation letter and requests management acknowledge the misstatements are immaterial, individually and in aggregate. Although the items are immaterial, they cannot simply be excluded from the letter — unlike mandatory correction, which is not required for immaterial items, the documentation requirement applies regardless of materiality.', 'medium', 3),

-- Q8: easy / L1 — Why written form is required
(1, 'Written Representations', 'Why does AU-C 580 require management representations to be in written form rather than oral form?', '["Oral representations are inadmissible as evidence in court proceedings", "Oral representations are entirely prohibited under generally accepted auditing standards", "Written representations constitute the highest and most persuasive form of audit evidence", "Written representations reduce the possibility of misunderstandings between management and the auditor"]'::jsonb, 3, 'Under AU-C 580.06, written representations are required because they reduce the possibility of misunderstandings between management and the auditor. Although oral representations through inquiry are still valid audit evidence and are not prohibited, putting representations in writing formalizes them and creates a clear documented record rather than relying on recollection of verbal discussions.', 'easy', 1),

-- Q9: hard / L3 — Group audit component management representations
(1, 'Written Representations', 'Landon & Pierce serves as the group engagement partner for the consolidated audit of Meridian Holdings and its three subsidiaries for the year ended December 31, 2025. A different firm, Ashford & Grant, audits the largest subsidiary, which accounts for 40% of consolidated revenue. The group engagement team is evaluating what written representations to obtain regarding the subsidiary. Under AU-C 600, the group engagement team should:', '["Request that component management provide written representations to the component auditor addressing matters relevant to the consolidation, and the component auditor should communicate relevant findings to the group engagement team", "Obtain written representations only from Meridian Holdings'' management, as a parent-level letter covers all subsidiaries automatically", "Require that the component auditor issue a separate audit opinion on the subsidiary before any representations are obtained", "Accept oral assurances from the subsidiary''s controller in lieu of a formal written representation letter"]'::jsonb, 0, 'Under AU-C 600.42, in a group audit the group engagement team should request that component management provide written representations to the component auditor covering matters relevant to the consolidation. Unlike a parent-level letter, which does not automatically cover subsidiaries, component-specific representations are necessary because each subsidiary''s management has direct knowledge of its own operations rather than relying solely on consolidated-level assertions.', 'hard', 3),

-- Q10: medium / L2 — Compliance with contractual agreements
(1, 'Written Representations', 'During the audit of Northfield Distribution Inc. for the year ended December 31, 2025, the engagement team at Waverly & Cole discovers that Northfield has a bank loan with several financial covenants. When preparing the management representation letter, the team requests a representation about contractual compliance. Under AU-C 580, management should represent that:', '["The auditor has independently verified compliance with all contractual obligations", "All aspects of contractual agreements that could affect the financial statements, including noncompliance, have been disclosed to the auditor", "The entity''s legal counsel has certified full compliance with every contract", "Contractual compliance is outside the scope of management''s representation responsibilities"]'::jsonb, 1, 'Under AU-C 580.A11, management should represent that all aspects of contractual agreements that may affect the financial statements have been considered and disclosed, including any noncompliance. However, the auditor does not independently verify compliance, nor does legal counsel''s certification replace management''s own representation — contractual matters that affect the financial statements fall squarely within management''s representation scope rather than outside it.', 'medium', 2),

-- Q11: medium / L3 — Fair value measurement representations
(1, 'Written Representations', 'The audit of Irongate Capital Partners for the year ended December 31, 2025 involves Level 3 fair value measurements of illiquid private equity investments totaling $12 million. The engagement team at Prescott & Lane drafts the management representation letter and considers what representation management should provide about these measurements. Under AU-C 580, management should represent that:', '["The auditor is responsible for determining the appropriate valuation methodology for all Level 3 measurements", "Fair value measurements were derived solely from independent third-party pricing services without management judgment", "The significant assumptions used in making the fair value measurements are reasonable and reflect management''s intent and ability to carry out specific courses of action", "Level 3 fair value measurements need not be addressed in the representation letter because they are inherently subjective"]'::jsonb, 2, 'Under AU-C 580.A11, management should represent that the significant assumptions used in fair value measurements are reasonable and reflect management''s intent and ability to carry out specific courses of action. In contrast to the view that subjective measurements should be excluded from the letter, their judgmental nature makes the representation especially important rather than optional.', 'medium', 3),

-- Q12: easy / L1 — Ownership and title to assets
(1, 'Written Representations', 'What does the management representation letter typically include regarding the entity''s assets under AU-C 580?', '["A statement that all assets were acquired at fair market value", "A list of every individual asset owned by the entity", "An assertion that the auditor has physically inspected all tangible assets", "A representation that the entity has satisfactory title to all owned assets and that there are no liens or encumbrances other than those disclosed"]'::jsonb, 3, 'Under AU-C 580.A12, the representation letter typically includes a statement that the entity has satisfactory title to all owned assets, free of liens or encumbrances except as disclosed. Unlike a requirement to list every individual asset, this representation supports the rights and obligations assertion at a financial statement level rather than requiring an item-by-item inventory in the letter.', 'easy', 1),

-- Q13: easy / L1 — Completeness of related party identification
(1, 'Written Representations', 'Under AU-C 580, what must management represent about related parties?', '["That all related party relationships and transactions have been identified, properly accounted for, and disclosed in the financial statements", "That the entity has no related party relationships of any kind", "That the auditor is responsible for identifying all related parties", "That related party transactions require separate audit reports"]'::jsonb, 0, 'Under AU-C 580.A13, management must represent the completeness of related party identification and that all relationships and transactions have been properly accounted for and disclosed. Although the auditor performs procedures to identify related parties, management bears primary responsibility for identification and disclosure rather than relying on the auditor to discover all related party relationships.', 'easy', 1),

-- Q14: medium / L3 — Significant assumptions in accounting estimates
(1, 'Written Representations', 'Thornfield Associates is auditing Quorum Insurance Group for the year ended December 31, 2025. Quorum''s financial statements include a $4.2 million loss reserve that relies on actuarial assumptions about claim frequency and severity. When preparing the management representation letter, Thornfield should ensure that management represents:', '["That the auditor''s independent actuarial calculation supersedes management''s estimate", "That the significant assumptions underlying accounting estimates, including the loss reserve, are reasonable in the circumstances", "That accounting estimates are excluded from the scope of management representations because they are inherently uncertain", "That the engagement team must hire its own actuary before any estimate-related representations are valid"]'::jsonb, 1, 'Under AU-C 580.A11, management should represent that the significant assumptions used in making accounting estimates are reasonable. Although estimates involve measurement uncertainty, they are not excluded from the representation letter — in contrast to the view that subjectivity eliminates the need for representation, the judgmental nature of estimates makes management''s written confirmation especially important.', 'medium', 3),

-- Q15: medium / L2 — Undisclosed side agreements
(1, 'Written Representations', 'During the audit of Fieldstone Logistics for the year ended December 31, 2025, the engagement team at Donovan & Patel suspects a revenue-sharing arrangement with a major customer that was not disclosed. When drafting the management representation letter, the team includes a representation about side agreements. Under AU-C 580, management should represent that:', '["All side agreements have been renegotiated and terminated before year-end", "Only agreements exceeding $1 million must be disclosed in the representation letter", "There are no side agreements, whether written or oral, that have not been disclosed to the auditor and reflected in the financial statements", "Side agreements are outside the scope of the management representation letter"]'::jsonb, 2, 'Under AU-C 580.A12, management should represent that there are no undisclosed side agreements, whether written or oral, that have not been properly disclosed and reflected in the financial statements. Unlike a dollar threshold approach, all such arrangements must be represented regardless of amount because even small undisclosed agreements may affect the completeness and accuracy of the financial statements.', 'medium', 2),

-- Q16: medium / L2 — Management responsibility for internal controls
(1, 'Written Representations', 'The audit team at Greystone & Marsh prepares the management representation letter for Pinnacle Retail Corp.''s December 31, 2025 audit. The CFO questions why the letter includes a representation about internal controls when the engagement is a financial statement audit, not an integrated audit. Under AU-C 580, the internal control representation is included because:', '["It is only required when the auditor issues a separate report on internal controls", "Internal control representations apply solely to public companies subject to PCAOB standards", "The representation is optional and may be omitted at management''s discretion during financial statement audits", "Management must acknowledge its responsibility for designing, implementing, and maintaining internal control relevant to the preparation and fair presentation of financial statements"]'::jsonb, 3, 'Under AU-C 580.11(c), management must represent its responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of the financial statements. Unlike an integrated audit opinion on internal controls, this representation is required in every financial statement audit rather than only in PCAOB engagements, because it reflects the fundamental premise that management is responsible for internal control.', 'medium', 2),

-- Q17: hard / L4 — Doubting specific but not all representations
(1, 'Written Representations', 'During the audit of Hawthorne Energy Group for the year ended December 31, 2025, the engagement partner at Caldwell & Sinclair has reason to doubt the reliability of management''s representation about the completeness of environmental liabilities but finds all other representations to be reliable. The partner must determine the appropriate course of action. Under AU-C 580, when the auditor has concerns about the reliability of specific, but not all, written representations, the auditor should:', '["Evaluate the effect on the audit by considering the specific representations in question, determining what additional audit evidence may be obtained, and assessing the impact on the auditor''s report if the concerns cannot be resolved", "Automatically issue a disclaimer of opinion because any doubt about any representation invalidates the entire letter", "Accept the remaining reliable representations and simply exclude the doubtful representation from the letter", "Require management to replace the individuals who provided the doubtful representations before continuing the audit"]'::jsonb, 0, 'Under AU-C 580.20, when the auditor has concerns about the reliability of specific representations, the auditor evaluates the effect on the audit — considering whether additional evidence can resolve the concern and the potential impact on the opinion. However, a doubt about one representation does not automatically invalidate the entire letter or trigger a disclaimer, unlike a situation where management refuses to provide any representations at all.', 'hard', 4),

-- Q18: medium / L2 — Claims and assessments representation
(1, 'Written Representations', 'Atlas Manufacturing is being audited by Fletcher & Dunn for the year ended December 31, 2025. Atlas has received a $2.5 million tax assessment from the IRS that management believes is without merit. When preparing the representation letter, the team considers the appropriate representation about this assessment. Under AU-C 580, management should represent that:', '["Tax assessments need not be mentioned in the representation letter if management considers them without merit", "All known claims and assessments, including the IRS assessment, have been disclosed to the auditor regardless of management''s view of the likely outcome", "Only tax assessments exceeding $5 million require disclosure in the representation letter", "The entity''s tax counsel has certified a favorable outcome for the assessment"]'::jsonb, 1, 'Under AU-C 580.A11, management must represent that all known claims and assessments whose effects should be considered when preparing the financial statements have been disclosed to the auditor. Unlike a threshold-based approach, there is no dollar minimum — all known claims must be disclosed regardless of amount because the auditor must independently evaluate the need for accrual or disclosure rather than relying on management''s merit assessment.', 'medium', 2),

-- Q19: hard / L4 — Initial audit year additional representations
(1, 'Written Representations', 'Crawford & Associates is performing the first-year audit of Summit Healthcare Corp. for the year ended December 31, 2025. The previous auditor, who audited the December 31, 2024 financial statements, issued an unmodified opinion. The engagement partner at Crawford considers whether additional representations beyond the standard AU-C 580 letter are needed for an initial engagement. In this situation, the engagement partner should:', '["Rely entirely on the predecessor auditor''s workpapers without obtaining any representations about prior-period balances", "Request only the standard representations since initial audit engagements have no additional representation requirements", "Request additional representations addressing matters specific to initial engagements, such as management''s assertion about the appropriateness of opening balances and the completeness of information provided regarding the predecessor auditor''s engagement", "Refuse to accept the engagement unless the predecessor auditor provides a separate written certification of the prior-year balances"]'::jsonb, 2, 'Under AU-C 580.A14, for initial audit engagements the auditor may request additional representations beyond the standard letter, such as management''s assertion about the appropriateness and completeness of opening balances. Although the predecessor auditor issued an unmodified opinion, the successor auditor cannot simply rely on prior workpapers without representations rather than independently addressing the unique risks associated with opening balances.', 'hard', 4),

-- Q20: easy / L1 — Commitments representation
(1, 'Written Representations', 'Under AU-C 580, what should management represent about commitments?', '["That the entity has no outstanding commitments of any kind", "That commitments are excluded from the scope of management representations", "That the auditor is responsible for identifying all material commitments", "That all commitments, such as purchase agreements and repurchase obligations, have been disclosed to the auditor"]'::jsonb, 3, 'Under AU-C 580.A12, management should represent that all commitments, including purchase agreements, repurchase obligations, and other contractual commitments, have been disclosed to the auditor. Although having no commitments would be unusual, management must still make an affirmative representation rather than remaining silent — identifying and disclosing commitments is management''s responsibility, unlike the auditor''s role of evaluating their treatment.', 'easy', 1),

-- Q21: easy / L1 — Subsequent events representation in the letter
(1, 'Written Representations', 'Under AU-C 580, which statement about subsequent events should the management representation letter include?', '["A representation that all events occurring after the balance sheet date through the date of the auditor''s report that require adjustment or disclosure have been properly addressed", "A statement that no events of any kind occurred between the balance sheet date and the report date", "A pledge that no subsequent events will occur after the auditor''s report is issued", "A representation that the auditor is solely responsible for identifying subsequent events"]'::jsonb, 0, 'Under AU-C 580.A13, the management representation letter should include a representation that all subsequent events occurring between the balance sheet date and the date of the auditor''s report that require adjustment or disclosure have been properly reflected. However, management cannot represent that no events occurred — the representation addresses proper treatment of events that did occur rather than the absence of events entirely.', 'easy', 1),

-- Q22: medium / L2 — Noncompliance with laws and regulations
(1, 'Written Representations', 'During the audit of Sterling Pharmaceuticals for the year ended December 31, 2025, the engagement team at Whitmore & Chen is aware that the entity operates in a heavily regulated industry. The team prepares the management representation letter and includes a representation about laws and regulations. Under AU-C 580, management should represent that:', '["The auditor has independently verified compliance with all applicable laws and regulations", "All known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements have been disclosed to the auditor", "Compliance with laws and regulations is outside the scope of a financial statement audit and need not be addressed in the letter", "Management has obtained legal opinions confirming full compliance with every applicable law and regulation"]'::jsonb, 1, 'Under AU-C 580.A11, management must represent that all known instances of noncompliance, or suspected noncompliance, with laws and regulations whose effects should be considered when preparing the financial statements have been disclosed. While the audit is not a compliance audit, noncompliance that affects the financial statements is within the auditor''s consideration rather than outside the scope of the representation letter.', 'medium', 2),

-- Q23: hard / L4 — Written representations as necessary but not sufficient
(1, 'Written Representations', 'During the audit of Vanguard Properties for the year ended December 31, 2025, a newly hired staff auditor at Mason & Forrest asks the engagement partner whether the signed management representation letter eliminates the need for additional substantive procedures in areas where management has provided detailed written assurances. The engagement partner should explain that under AU-C 580, written representations:', '["Replace the need for confirmation procedures but not for analytical procedures", "Serve as the highest quality evidence and can replace all other procedures for assertions covered by the letter", "Are necessary audit evidence that complement but do not replace other substantive procedures the auditor is required to perform based on assessed risks", "May replace substantive procedures at the auditor''s discretion when management''s written assurances are deemed highly reliable"]'::jsonb, 2, 'Under AU-C 580.04, written representations are necessary information that the auditor requests from management, but they do not provide sufficient appropriate audit evidence on their own. Although the letter is an important component of audit evidence, treating it as the highest-quality evidence would be incorrect because representations complement rather than replace other procedures required by the assessed risk of material misstatement.', 'hard', 4),

-- Q24: easy / L1 — Retention of representation letter in audit documentation
(1, 'Written Representations', 'Where should the auditor retain the signed management representation letter?', '["In the entity''s corporate minutes file", "In the entity''s permanent legal records", "With the applicable regulatory agency", "In the auditor''s audit documentation (workpapers) for the engagement"]'::jsonb, 3, 'Under AU-C 580.A42 and AU-C 230, the signed management representation letter is retained as part of the auditor''s audit documentation (workpapers). Unlike corporate minutes or regulatory filings, the letter is audit evidence obtained by the auditor and must be included in the engagement file rather than filed with external parties or the entity''s own records.', 'easy', 1),

-- Q25: hard / L4 — Management specialist and representations
(1, 'Written Representations', 'During the audit of Cedarbrook Insurance Corp. for the year ended December 31, 2025, management engaged an independent actuary to estimate claim loss reserves of $8.5 million. The engagement team at Rutherford & Keane evaluates whether the management representation letter should address management''s use of this specialist. Under AU-C 580, the engagement team should:', '["Request that management represent it has evaluated the actuary''s competence, capabilities, and objectivity, and that it takes responsibility for the assumptions and methods used by the specialist in developing the estimate", "Omit any mention of the actuary because management''s use of a specialist eliminates the need for a management representation about the related estimate", "Require the actuary to sign the management representation letter alongside the CEO and CFO", "Accept the actuary''s report as a substitute for any management representation about claim loss reserves"]'::jsonb, 0, 'Under AU-C 580.A15, when management uses a specialist, the representation letter should address management''s evaluation of the specialist''s competence, capabilities, and objectivity, and confirm that management takes responsibility for the assumptions and methods used. Unlike the view that a specialist''s involvement eliminates the need for representation, management''s responsibility for the estimate is not relieved by engaging a specialist — rather than having the actuary sign the letter, management must affirm its own oversight.', 'hard', 4),

-- Q26: easy / L2 — Completeness of minutes of meetings
(1, 'Written Representations', 'The engagement team at Lawson & Drake finalizes the management representation letter for Brookdale Corp.''s December 31, 2025 audit. A first-year associate asks what the letter should say about the entity''s board meeting minutes. Under AU-C 580, management should represent that:', '["Board meeting minutes are irrelevant to the financial statement audit", "The minutes of all meetings of shareholders, directors, and committees of directors have been made available to the auditor, and they are complete through the date of the letter", "Only minutes from the final quarter of the fiscal year must be provided to the auditor", "The auditor is responsible for independently obtaining all board meeting minutes"]'::jsonb, 1, 'Under AU-C 580.11(b), management represents that the minutes of all meetings of shareholders, directors, and committees of directors have been made available and are complete. Unlike a partial-year requirement, the representation covers all meetings rather than only the final quarter, because significant decisions and commitments may occur at any point during the year.', 'easy', 2),

-- Q27: medium / L3 — Representation about all transactions properly recorded
(1, 'Written Representations', 'During the audit of Haverford Electronics for the year ended December 31, 2025, the engagement team at Sinclair & Blake discovers that several material sales transactions in November were not recorded until January 2026. The team prepares the management representation letter. Under AU-C 580, the representation about transactions being properly recorded supports which primary assertion?', '["Valuation", "Presentation and disclosure", "Completeness", "Classification"]'::jsonb, 2, 'Under AU-C 580.11(a), management represents that all transactions have been recorded and are reflected in the financial statements. This representation primarily supports the completeness assertion — the assertion that all transactions and events that should have been recorded have been included. While valuation and presentation are also addressed in the letter, the recording of transactions directly relates to completeness rather than how amounts are measured or displayed.', 'medium', 3),

-- Q28: medium / L3 — Absence of liens and encumbrances
(1, 'Written Representations', 'Summit Construction Inc. pledged its fleet of construction equipment as collateral for a $3.2 million line of credit during 2025. The engagement team at Norwood & Avery prepares the management representation letter for the December 31, 2025 audit and includes a representation about liens. Under AU-C 580, management should represent that:', '["All equipment liens must be removed before the representation letter can be signed", "Pledged assets need not be mentioned in the representation letter if they are properly recorded in the general ledger", "The auditor is responsible for independently discovering all liens through public records searches", "All liens, encumbrances, and security interests on assets have been properly disclosed in the financial statements"]'::jsonb, 3, 'Under AU-C 580.A12, management should represent that all liens, pledges, and encumbrances on assets have been disclosed. Although the equipment pledge may be properly recorded in the general ledger, management must still affirmatively represent completeness of lien disclosures in the letter rather than relying on ledger entries alone, because the representation covers all encumbrances, not only those already recorded.', 'medium', 3),

-- Q29: medium / L2 — Professional skepticism and written representations
(1, 'Written Representations', 'During the audit of Aldridge & Sons Manufacturing for the year ended December 31, 2025, the engagement partner at Brentwood & Shaw receives a comprehensive management representation letter covering all required matters. A staff auditor asks whether receiving the letter means the team can accept management''s assertions at face value. Under AU-C 580, the engagement partner should explain that:', '["The auditor must still exercise professional skepticism and cannot treat written representations as a substitute for applying audit procedures to corroborate management''s assertions", "A signed representation letter legally binds management and the auditor may therefore rely on it without further procedures", "Professional skepticism is suspended once the representation letter is received", "The representation letter is presumed accurate unless the auditor discovers a direct contradiction in the financial statements"]'::jsonb, 0, 'Under AU-C 580.A19, the auditor must exercise professional skepticism when evaluating written representations and cannot treat them as a substitute for applying audit procedures. Although the letter is signed and formalized, it does not legally bind management in a way that eliminates the need for skepticism — the auditor must remain alert for contradictory evidence rather than presuming accuracy simply because the letter has been signed.', 'medium', 2),

-- Q30: hard / L4 — Special purpose framework representations
(1, 'Written Representations', 'Redfield Community Services, a nonprofit organization, prepares its financial statements on the cash basis of accounting — a special purpose framework. The engagement team at Montgomery & Park is finalizing the December 31, 2025 audit and drafting the management representation letter. Under AU-C 800, the representation letter for a special purpose framework engagement should include:', '["Only the standard representations required by AU-C 580, with no additional considerations for the special purpose framework", "An additional representation that management considers the cash basis of accounting acceptable as a financial reporting framework in the circumstances and that the financial statements include all informative disclosures appropriate for the special purpose framework", "A statement that the auditor has approved the use of the cash basis framework for this entity", "A representation that the financial statements would be materially identical if prepared under GAAP"]'::jsonb, 1, 'Under AU-C 800.13, when auditing financial statements prepared on a special purpose framework, the representation letter should include additional representations beyond AU-C 580 — specifically, that management considers the framework acceptable and that all appropriate informative disclosures are included. Unlike a standard GAAP audit, special purpose framework engagements require these additional representations rather than relying solely on the standard letter.', 'hard', 4)
;

COMMIT;
